import{_ as t,C as e,o as n,c as i,E as r,a2 as l}from"./chunks/framework.Cm6XCzck.js";const b=JSON.parse('{"title":"开源工程观察周报 002 — 智能体能力正在被封装为技能、插件与契约","description":"","frontmatter":{"title":"开源工程观察周报 002 — 智能体能力正在被封装为技能、插件与契约","date":"2026-08-02","column":"open-source-engineering","category":"weekly","summary":"OpenHands、CrewAI、AutoGen 与 LangGraph 显示，可复用智能体能力正从隐藏提示词转向显式技能、插件、工具、工作流、消息契约与结构化事件。","sources":["OpenHands 技能与插件文档","CrewAI 智能体、流程与可观测性文档","AutoGen 团队、应用栈、记忆与日志文档","LangGraph 运行时与人在回路文档"],"outline":"deep","cover":"/assets/covers/agent-capability-packaging-cover-v2.jpg"},"headers":[],"relativePath":"zh/engineering/2026-08-02-agent-capability-packaging.md","filePath":"zh/engineering/2026-08-02-agent-capability-packaging.md","lastUpdated":1787407830000}'),o={name:"zh/engineering/2026-08-02-agent-capability-packaging.md"};function p(d,a,h,g,c,k){const s=e("ArticleCover");return n(),i("div",null,[r(s,{image:"/assets/covers/agent-capability-packaging-cover-v2.jpg",kicker:"开源工程观察 · 周报 002",title:"智能体能力正在被封装为技能、插件与契约",summary:"可复用能力正在离开隐藏提示词，进入显式能力包、接口、工作流节点与事件。",version:"EW002",status:"发布于 2026-08-02",languageHref:"/en/engineering/2026-08-02-agent-capability-packaging",languageLabel:"English"}),a[0]||(a[0]=l(`<h2 id="摘要" tabindex="-1">摘要 <a class="header-anchor" href="#摘要" aria-label="Permalink to &quot;摘要&quot;">​</a></h2><p>第二个开源工程信号，是智能体能力的表达方式正在改变。早期系统常把能力藏在一段很长的提示词和一个不受限制的工具列表中；当前系统越来越多地把能力封装为可检查的显式组件。</p><p>OpenHands 使用技能、钩子、MCP 配置、专用智能体、命令与插件；CrewAI 分离智能体、任务、工具、团队、流程、护栏、记忆、知识和结构化输出；AutoGen 将 AgentChat 团队与事件驱动核心分开，并要求应用定义消息契约；LangGraph 将节点、状态、边、中断和持久化作为显式编排组件。</p><p>本周判断是：</p><blockquote><p>可复用智能体能力正在成为受治理的能力包，需要名称、范围、激活规则、接口、版本、运行时依赖、事件面和证据链。单独一段提示词不能构成完整的技能契约。</p></blockquote><h2 id="资料来源" tabindex="-1">资料来源 <a class="header-anchor" href="#资料来源" aria-label="Permalink to &quot;资料来源&quot;">​</a></h2><p>本周选择以下官方资料，覆盖四个互补方向：</p><ol><li><strong>OpenHands 技能与插件</strong>：<code>SKILL.md</code>、常驻上下文、按需触发技能、插件包、钩子、MCP 服务器、智能体与命令。</li><li><strong>CrewAI 智能体与流程</strong>：岗位化智能体、工具、记忆、知识、结构化输出、持久流程、护栏、回调与可观测性。</li><li><strong>AutoGen 团队与核心</strong>：团队模式、交接、事件驱动运行时、消息协议、记忆接口、状态序列化与结构化日志。</li><li><strong>LangGraph 编排</strong>：显式状态、节点、转换、中断、持久化与人工决策点。</li></ol><p>这些资料揭示了工程模式，但尚不能证明存在一个统一的技能封装标准。</p><h2 id="本周要点" tabindex="-1">本周要点 <a class="header-anchor" href="#本周要点" aria-label="Permalink to &quot;本周要点&quot;">​</a></h2><h3 id="_1-技能正从提示词文本转向可加载工件" tabindex="-1">1. 技能正从提示词文本转向可加载工件 <a class="header-anchor" href="#_1-技能正从提示词文本转向可加载工件" aria-label="Permalink to &quot;1. 技能正从提示词文本转向可加载工件&quot;">​</a></h3><p>OpenHands 把技能定义为增强智能体的专门知识和工作方式，并通过文件和明确的加载行为进行封装。常驻上下文与按需技能分开；关键词触发或智能体自主选择支持渐进式披露；组织、用户和仓库级范围也被区分。</p><p>这比把所有规则复制进每次系统提示词更容易维护和审计。</p><h3 id="_2-插件正在成为能力组合包" tabindex="-1">2. 插件正在成为能力组合包 <a class="header-anchor" href="#_2-插件正在成为能力组合包" aria-label="Permalink to &quot;2. 插件正在成为能力组合包&quot;">​</a></h3><p>OpenHands 插件可以同时包含技能、钩子、MCP 配置、专用智能体与命令。重要变化是：一个能力包可以同时携带知识和运行时集成。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>能力包</span></span>
<span class="line"><span>  ├── 技能指令</span></span>
<span class="line"><span>  ├── 工具 / MCP 绑定</span></span>
<span class="line"><span>  ├── 生命周期钩子</span></span>
<span class="line"><span>  ├── 专用智能体定义</span></span>
<span class="line"><span>  ├── 命令</span></span>
<span class="line"><span>  └── 带版本的包元数据</span></span></code></pre></div><p><em>图：JoinWell52 研究中心根据 OpenHands 插件文档整理。</em></p><h3 id="_3-工作流系统正在分离能力与编排" tabindex="-1">3. 工作流系统正在分离能力与编排 <a class="header-anchor" href="#_3-工作流系统正在分离能力与编排" aria-label="Permalink to &quot;3. 工作流系统正在分离能力与编排&quot;">​</a></h3><p>CrewAI 将智能体和工具同负责路由、持久化与恢复的流程分开；LangGraph 将节点行为同状态、转换分开；AutoGen 将智能体同团队模式、事件驱动运行时分开。</p><p>这让同一技能或工具可以在不同工作流中复用，而不需要重新定义完整的数字员工。</p><h3 id="_4-消息与事件契约正变得重要" tabindex="-1">4. 消息与事件契约正变得重要 <a class="header-anchor" href="#_4-消息与事件契约正变得重要" aria-label="Permalink to &quot;4. 消息与事件契约正变得重要&quot;">​</a></h3><p>AutoGen 应用栈要求开发者把消息类型定义为行为契约，并把追踪日志与结构化事件分离。这表明智能体交互需要机器可读接口，而不仅是自由文本。</p><p>当其他组件无法判断以下内容时，一个能力在工程上仍不完整：</p><ul><li>接受什么输入；</li><li>承诺什么输出；</li><li>发出什么事件；</li><li>可以返回什么错误或暂停状态；</li><li>需要什么权限；</li><li>如何进行版本管理。</li></ul><h2 id="交叉分析" tabindex="-1">交叉分析 <a class="header-anchor" href="#交叉分析" aria-label="Permalink to &quot;交叉分析&quot;">​</a></h2><h3 id="能力表达矩阵" tabindex="-1">能力表达矩阵 <a class="header-anchor" href="#能力表达矩阵" aria-label="Permalink to &quot;能力表达矩阵&quot;">​</a></h3><table tabindex="0"><thead><tr><th>维度</th><th>OpenHands</th><th>CrewAI</th><th>AutoGen</th><th>LangGraph</th></tr></thead><tbody><tr><td>主要能力单元</td><td>技能 / 插件 / 智能体 / 命令</td><td>智能体 / 工具 / 任务 / 团队</td><td>智能体 / 团队 / 消息处理器</td><td>节点 / 可运行单元 / 图</td></tr><tr><td>激活方式</td><td>常驻、用户触发、关键词或智能体选择</td><td>任务 / 过程 / 流程调用</td><td>运行时消息、团队选择、交接</td><td>边、条件、中断、命令</td></tr><tr><td>工具集成</td><td>插件与 MCP 配置</td><td>智能体工具与集成工具</td><td>可调用工具的智能体与扩展</td><td>工具节点与应用代码</td></tr><tr><td>状态</td><td>对话与工作区上下文</td><td>流程与团队状态</td><td>智能体 / 团队状态与记忆协议</td><td>显式图状态与检查点</td></tr><tr><td>接口契约</td><td>技能格式与插件结构</td><td>结构化输入输出与 Pydantic 模型</td><td>消息协议与事件类型</td><td>状态模式与节点转换契约</td></tr><tr><td>可观测性</td><td>运行时 / 插件日志与钩子</td><td>追踪、回调、监控</td><td>追踪日志与结构化事件日志</td><td>状态历史与追踪集成</td></tr><tr><td>分发方式</td><td>注册表 / 仓库包</td><td>项目包与托管平台</td><td>Python 组件与分布式运行时</td><td>库、部署与运行时服务</td></tr></tbody></table><p><strong>说明：</strong> 本表比较官方抽象，不代表功能等价或质量评测。</p><h3 id="建议的最小技能契约" tabindex="-1">建议的最小技能契约 <a class="header-anchor" href="#建议的最小技能契约" aria-label="Permalink to &quot;建议的最小技能契约&quot;">​</a></h3><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">skill</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  id</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  version</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  purpose</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  activation</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  input_contract</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  output_contract</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  allowed_tools</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  required_authority</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  runtime_dependencies</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  emitted_events</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  failure_states</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  evidence_requirements</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  owner</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span></code></pre></div><p>这是研究中心提出的研究投影，不是已经冻结的产品数据模式。</p><h2 id="新架构判断" tabindex="-1">新架构判断 <a class="header-anchor" href="#新架构判断" aria-label="Permalink to &quot;新架构判断&quot;">​</a></h2><ol><li><strong>技能应是显式工件。</strong> 隐藏提示词无法可靠发现、版本化、激活和审计。</li><li><strong>能力与工作流必须分开。</strong> 技能说明可以做什么；工作流决定何时以及按什么顺序使用。</li><li><strong>插件可以把知识绑定到运行时基础设施。</strong> 这很强，但也扩大了安全与审查边界。</li><li><strong>消息与事件契约是多智能体组合的必要条件。</strong> 自由文本不足以支持可靠编排。</li><li><strong>激活状态必须可观察。</strong> 已安装、已加载、已选择、已执行与已验证是不同状态。</li></ol><h2 id="工程影响" tabindex="-1">工程影响 <a class="header-anchor" href="#工程影响" aria-label="Permalink to &quot;工程影响&quot;">​</a></h2><h3 id="tmpa" tabindex="-1">TMPA <a class="header-anchor" href="#tmpa" aria-label="Permalink to &quot;TMPA&quot;">​</a></h3><p>本报告不修改 TMPA 正式出版物。作为研究输入，它支持在能力激活与执行过程中，明确角色、权限、消息、事件、生命周期和完整性之间的引用关系。</p><h3 id="数字员工" tabindex="-1">数字员工 <a class="header-anchor" href="#数字员工" aria-label="Permalink to &quot;数字员工&quot;">​</a></h3><p>数字员工应拥有受治理的能力目录。每项技能需要范围、版本、负责人、权限要求、运行时绑定、证据要求与评估历史。</p><h3 id="codeflowmu" tabindex="-1">CodeFlowMu <a class="header-anchor" href="#codeflowmu" aria-label="Permalink to &quot;CodeFlowMu&quot;">​</a></h3><p>CodeFlowMu 当前已经加载技能并记录工具使用情况，但产品需要明确区分：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>available</span></span>
<span class="line"><span>→ installed</span></span>
<span class="line"><span>→ activated</span></span>
<span class="line"><span>→ invoked</span></span>
<span class="line"><span>→ completed</span></span>
<span class="line"><span>→ verified</span></span></code></pre></div><p>运行时应记录每个工作单实际启用了哪个技能版本，以及产生了哪些结构化事件与证据。上面的英文状态词是建议保留在系统中的稳定标识，面向用户时应同时提供中文解释。</p><h2 id="下周研究" tabindex="-1">下周研究 <a class="header-anchor" href="#下周研究" aria-label="Permalink to &quot;下周研究&quot;">​</a></h2><ol><li>比较 AgentSkills、Claude Code 插件、MCP 服务器与框架专用工具。</li><li>为 CodeFlowMu 定义可移植的技能契约。</li><li>研究第三方能力包的签名、信任和权限模型。</li><li>测试同一技能在不同智能体提供商环境下能否保持一致行为。</li></ol><h2 id="参考资料" tabindex="-1">参考资料 <a class="header-anchor" href="#参考资料" aria-label="Permalink to &quot;参考资料&quot;">​</a></h2><ol><li>OpenHands，<strong>技能概览</strong>：<a href="https://docs.openhands.dev/overview/skills" target="_blank" rel="noreferrer">https://docs.openhands.dev/overview/skills</a></li><li>OpenHands，<strong>组织与用户技能</strong>：<a href="https://docs.openhands.dev/overview/skills/org" target="_blank" rel="noreferrer">https://docs.openhands.dev/overview/skills/org</a></li><li>OpenHands，<strong>添加新技能</strong>：<a href="https://docs.openhands.dev/overview/skills/adding" target="_blank" rel="noreferrer">https://docs.openhands.dev/overview/skills/adding</a></li><li>OpenHands，<strong>插件</strong>：<a href="https://docs.openhands.dev/sdk/guides/plugins" target="_blank" rel="noreferrer">https://docs.openhands.dev/sdk/guides/plugins</a></li><li>CrewAI，<strong>文档</strong>：<a href="https://docs.crewai.com/" target="_blank" rel="noreferrer">https://docs.crewai.com/</a></li><li>CrewAI，<strong>CrewAI AMP</strong>：<a href="https://docs.crewai.com/enterprise/introduction" target="_blank" rel="noreferrer">https://docs.crewai.com/enterprise/introduction</a></li><li>Microsoft AutoGen，<strong>团队</strong>：<a href="https://microsoft.github.io/autogen/stable/user-guide/agentchat-user-guide/tutorial/teams.html" target="_blank" rel="noreferrer">https://microsoft.github.io/autogen/stable/user-guide/agentchat-user-guide/tutorial/teams.html</a></li><li>Microsoft AutoGen，<strong>应用栈</strong>：<a href="https://microsoft.github.io/autogen/stable/user-guide/core-user-guide/core-concepts/application-stack.html" target="_blank" rel="noreferrer">https://microsoft.github.io/autogen/stable/user-guide/core-user-guide/core-concepts/application-stack.html</a></li><li>Microsoft AutoGen，<strong>记忆与检索增强生成</strong>：<a href="https://microsoft.github.io/autogen/stable/user-guide/agentchat-user-guide/memory.html" target="_blank" rel="noreferrer">https://microsoft.github.io/autogen/stable/user-guide/agentchat-user-guide/memory.html</a></li><li>Microsoft AutoGen，<strong>日志</strong>：<a href="https://microsoft.github.io/autogen/stable/user-guide/core-user-guide/framework/logging.html" target="_blank" rel="noreferrer">https://microsoft.github.io/autogen/stable/user-guide/core-user-guide/framework/logging.html</a></li><li>LangChain，<strong>LangGraph 概览</strong>：<a href="https://docs.langchain.com/oss/python/langgraph/overview" target="_blank" rel="noreferrer">https://docs.langchain.com/oss/python/langgraph/overview</a></li></ol>`,46))])}const m=t(o,[["render",p]]);export{b as __pageData,m as default};
